create table public.icash_wallets (account_id uuid not null,balance_cents bigint not null default 0,reserved_cents bigint not null default 0,currency text not null default 'USD'::text,CHECK ((balance_cents >= 0)),CHECK (((reserved_cents >= 0) AND (reserved_cents <= balance_cents))),CHECK ((currency = 'USD'::text)),PRIMARY KEY (account_id));
